3	import (
4		"bytes"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// Header roots are arbitrary byte strings compared byte for byte. A root
13	// holding invalid UTF-8 bytes must survive saving, reopening and log
14	// compaction exactly: JSON string encoding would otherwise silently rewrite
15	// such bytes to U+FFFD, making the resubmitted original root conflict with
16	// its own saved value while the replacement character is wrongly accepted.
17	
18	const replacementCharRoot = "�"
19	
20	// requireHeaderAccepted requires a trusted same-height save of root to be
21	// accepted against the currently accepted trusted root.
22	func requireHeaderAccepted(t *testing.T, q *Queue, chain string, height int64, root string) {
23		t.Helper()
24		if err := q.UpsertHeader(Header{Chain: chain, Height: height, Root: root, Trusted: true}); err != nil {
25			t.Fatalf("same root at trusted height %d must be accepted: %v", height, err)
26		}
27	}
28	
29	// requireHeaderConflict requires a trusted same-height save of root to fail
30	// with ErrHeaderConflict, and the accepted trusted root to stay wantAccepted.
31	func requireHeaderConflict(t *testing.T, q *Queue, chain string, height int64, root, wantAccepted string) {
32		t.Helper()
33		err := q.UpsertHeader(Header{Chain: chain, Height: height, Root: root, Trusted: true})
34		if !errors.Is(err, ErrHeaderConflict) {
35			t.Fatalf("different root at trusted height %d: want ErrHeaderConflict, got %v", height, err)
36		}
37		hs := q.headers[chain]
38		if hs == nil || hs.trusted == nil || hs.trusted.Root != wantAccepted || hs.trusted.Height != height {
39			t.Fatalf("accepted trusted header changed after conflict: %+v", hs.trusted)
40		}
41	}
42	
43	func reopen(t *testing.T, dir string) *Queue {
44		t.Helper()
45		q, err := Open(dir)
46		if err != nil {
47			t.Fatalf("reopen: %v", err)
48		}
49		return q
50	}
51	
52	// An invalid-UTF-8 root is preserved byte-for-byte through save, close,
53	// reopen and compaction: the identical byte sequence stays an idempotent
54	// accept at the trusted height, while a root differing in any byte — and the
55	// legal character U+FFFD, which must never be merged with invalid bytes —
56	// conflicts, before and after every persistence boundary.
57	func TestHeaderRootInvalidUTF8PreservedAcrossReopenAndCompaction(t *testing.T) {
58		rootFF := string([]byte{0xFF})
59		rootFE := string([]byte{0xFE})
60		mixed := "pre" + string([]byte{0xFF}) + "post"
61	
62		dir := t.TempDir()
63		q, err := Open(dir)
64		if err != nil {
65			t.Fatal(err)
66		}
67		if err := q.RegisterSource("a"); err != nil {
68			t.Fatal(err)
69		}
70		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: rootFF, Trusted: true}); err != nil {
71			t.Fatalf("save invalid-UTF-8 root: %v", err)
72		}
73		if err := q.UpsertHeader(Header{Chain: "b", Height: 7, Root: mixed, Trusted: true}); err != nil {
74			t.Fatalf("save partially invalid root: %v", err)
75		}
76	
77		check := func(t *testing.T, q *Queue) {
78			t.Helper()
79			// The exact same bytes are accepted idempotently.
80			requireHeaderAccepted(t, q, "a", 100, rootFF)
81			requireHeaderAccepted(t, q, "b", 7, mixed)
82			// Any single-byte difference is a conflict, and U+FFFD is a distinct
83			// root, never the canonical form of invalid bytes.
84			requireHeaderConflict(t, q, "a", 100, rootFE, rootFF)
85			requireHeaderConflict(t, q, "a", 100, replacementCharRoot, rootFF)
86			requireHeaderConflict(t, q, "b", 7, replacementCharRoot, mixed)
87		}
88		t.Run("same instance", func(t *testing.T) { check(t, q) })
89		if err := q.Close(); err != nil {
90			t.Fatal(err)
91		}
92	
93		q = reopen(t, dir)
94		t.Run("after reopen", func(t *testing.T) { check(t, q) })
95	
96		// A higher untrusted header and a lower trusted header with different
97		// roots are recorded but never displace the accepted trusted root.
98		if err := q.UpsertHeader(Header{Chain: "a", Height: 200, Root: rootFE, Trusted: false}); err != nil {
99			t.Fatal(err)
100		}
101		if err := q.UpsertHeader(Header{Chain: "a", Height: 50, Root: rootFE, Trusted: true}); err != nil {
102			t.Fatal(err)
103		}
104		check(t, q)
105	
106		// Force a compaction cycle; the snapshot must carry the exact bytes too.
107		if err := q.store.compact(q.snapshot()); err != nil {
108			t.Fatalf("compact: %v", err)
109		}
110		if err := q.Close(); err != nil {
111			t.Fatal(err)
112		}
113	
114		q = reopen(t, dir)
115		t.Run("after compaction and reopen", func(t *testing.T) { check(t, q) })
116		if err := q.Close(); err != nil {
117			t.Fatal(err)
118		}
119	
120		// The persisted log holds the raw bytes base64-encoded and never the
121		// replacement character.
122		raw, err := os.ReadFile(filepath.Join(dir, logName))
123		if err != nil {
124			t.Fatal(err)
125		}
126		if !bytes.Contains(raw, []byte(`"rootB64":"`)) {
127			t.Fatalf("invalid-UTF-8 root not stored byte-exactly: %s", raw)
128		}
129		if bytes.Contains(raw, []byte(replacementCharRoot)) {
130			t.Fatalf("log contains U+FFFD: a root was silently rewritten: %s", raw)
131		}
132	}
133	
134	// Valid-UTF-8 roots — plain text, empty, whitespace, U+FFFD itself — keep the
135	// historical plain "root" field, so logs written by older builds and this
136	// build remain byte-identical and existing state directories keep working.
137	func TestHeaderRootValidUTF8KeepsHistoricalEncoding(t *testing.T) {
138		dir := t.TempDir()
139		q, err := Open(dir)
140		if err != nil {
141			t.Fatal(err)
142		}
143		roots := []string{"0xaaa", "", " spaced ", replacementCharRoot}
144		for i, root := range roots {
145			chain := string(rune('c' + i))
146			if err := q.UpsertHeader(Header{Chain: chain, Height: 5, Root: root, Trusted: true}); err != nil {
147				t.Fatalf("save root %q: %v", root, err)
148			}
149		}
150		if err := q.Close(); err != nil {
151			t.Fatal(err)
152		}
153	
154		raw, err := os.ReadFile(filepath.Join(dir, logName))
155		if err != nil {
156			t.Fatal(err)
157		}
158		if bytes.Contains(raw, []byte("rootB64")) {
159			t.Fatalf("valid-UTF-8 roots must keep the plain root field: %s", raw)
160		}
161		if !bytes.Contains(raw, []byte(`"root":"0xaaa"`)) {
162			t.Fatalf("plain root missing from log: %s", raw)
163		}
164	
165		// Reopen: every root means exactly what it meant before, including the
166		// empty root and U+FFFD as an ordinary legal character.
167		q = reopen(t, dir)
168		defer q.Close()
169		for i, root := range roots {
170			requireHeaderAccepted(t, q, string(rune('c'+i)), 5, root)
171		}
172		requireHeaderConflict(t, q, "c", 5, "0xAAA", "0xaaa")
173		requireHeaderConflict(t, q, "d", 5, "other", "")
174		requireHeaderConflict(t, q, "f", 5, string([]byte{0xFF}), replacementCharRoot)
175	}
176	
177	// A state directory written by an older build may already hold a root that
178	// was silently rewritten to U+FFFD. Replay takes the saved characters at face
179	// value — the lost bytes are never guessed — so the replacement character is
180	// the accepted root and the original invalid bytes conflict with it.
181	func TestHeaderRootLegacyReplacementCharTakenAtFaceValue(t *testing.T) {
182		dir := t.TempDir()
183		var raw []byte
184		raw = append(raw, logMagic...)
185		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
186		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
187			T: kindHeader, Chain: "a", Height: 100, Root: replacementCharRoot, Trusted: true,
188		}))...)
189		writeRawLog(t, dir, raw)
190	
191		q := reopen(t, dir)
192		defer q.Close()
193		requireHeaderAccepted(t, q, "a", 100, replacementCharRoot)
194		requireHeaderConflict(t, q, "a", 100, string([]byte{0xFF}), replacementCharRoot)
195	}
196	
197	// A rootB64 entry must decode unambiguously: an entry carrying both root and
198	// rootB64, or an undecodable rootB64, is an inconsistent record no build
199	// writes and rejects the directory as corrupt, leaving every byte untouched.
200	//
201	// Presence is judged by key, not by value: "root":"" is a legal empty root on
202	// its own, but together with any rootB64 it is two representations at once —
203	// even when one side is empty, and even when the two decode to the same
204	// bytes. Every such record below is complete and checksum-valid and sits at
205	// the end of the log, so it must be rejected as corruption, never dropped as a
206	// torn tail; trusted and untrusted headers alike.
207	func TestHeaderRootB64InconsistentRecordsRejected(t *testing.T) {
208		// Struct-built cases: omitempty drops an empty Root, so the non-empty
209		// plain clash and the undecodable base64 can use the typed entry.
210		structEntries := map[string]*logEntry{
211			"both root and rootB64": {T: kindHeader, Chain: "a", Height: 1, Root: "x", RootB64: "eA==", Trusted: true},
212			"undecodable rootB64":   {T: kindHeader, Chain: "a", Height: 1, RootB64: "!!!not-base64!!!", Trusted: true},
213		}
214		// Raw-JSON cases: the "root":"" key must literally be present, which the
215		// omitempty struct tag would erase on marshal.
216		rawPayloads := map[string]string{
217			"empty root plus rootB64 of 0xff (trusted)":    `{"t":"header","chain":"a","height":1,"trusted":true,"root":"","rootB64":"/w=="}`,
218			"empty root plus rootB64 of 0xff (untrusted)":  `{"t":"header","chain":"a","height":1,"trusted":false,"root":"","rootB64":"/w=="}`,
219			"empty root plus empty rootB64, equal decoded": `{"t":"header","chain":"a","height":1,"trusted":true,"root":"","rootB64":""}`,
220			"plain and rootB64 decode to the same bytes":   `{"t":"header","chain":"a","height":1,"trusted":true,"rootB64":"eA==","root":"x"}`,
221		}
222		for name, e := range structEntries {
223			t.Run(name, func(t *testing.T) {
224				dir := t.TempDir()
225				var raw []byte
226				raw = append(raw, logMagic...)
227				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
228				raw = append(raw, encodeFrame(mustMarshal(e))...)
229				writeRawLog(t, dir, raw)
230				assertCorruptAndUntouched(t, dir, raw)
231			})
232		}
233		for name, payload := range rawPayloads {
234			t.Run(name, func(t *testing.T) {
235				dir := t.TempDir()
236				var raw []byte
237				raw = append(raw, logMagic...)
238				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
239				raw = append(raw, encodeFrame([]byte(payload))...)
240				writeRawLog(t, dir, raw)
241				assertCorruptAndUntouched(t, dir, raw)
242			})
243		}
244	}
245	
246	// The empty root keeps its long-standing meaning through every legal on-disk
247	// shape, and a sole rootB64 still restores its bytes: the new presence-based
248	// clash check must never mistake an omitted key for an empty-but-present one.
249	func TestHeaderRootEmptyOmittedAndSoleB64StillAccepted(t *testing.T) {
250		rootFF := string([]byte{0xFF})
251		cases := map[string]struct {
252			payload      string
253			wantRoot     string
254			conflictRoot string
255		}{
256			"explicit empty root": {
257				payload:      `{"t":"header","chain":"a","height":10,"trusted":true,"root":""}`,
258				wantRoot:     "",
259				conflictRoot: "other",
260			},
261			"both root keys omitted (historical empty root)": {
262				payload:      `{"t":"header","chain":"a","height":10,"trusted":true}`,
263				wantRoot:     "",
264				conflictRoot: "other",
265			},
266			"sole rootB64 restores its bytes": {
267				payload:      `{"t":"header","chain":"a","height":10,"trusted":true,"rootB64":"/w=="}`,
268				wantRoot:     rootFF,
269				conflictRoot: "",
270			},
271		}
272		for name, tc := range cases {
273			t.Run(name, func(t *testing.T) {
274				dir := t.TempDir()
275				var raw []byte
276				raw = append(raw, logMagic...)
277				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
278				raw = append(raw, encodeFrame([]byte(tc.payload))...)
279				writeRawLog(t, dir, raw)
280	
281				q := reopen(t, dir)
282				defer q.Close()
283				// The restored root is accepted idempotently at the trusted height,
284				// proving its exact bytes survived.
285				requireHeaderAccepted(t, q, "a", 10, tc.wantRoot)
286				// A different root at the same height still conflicts, proving the
287				// restored value is the real root, not a conflated empty one.
288				requireHeaderConflict(t, q, "a", 10, tc.conflictRoot, tc.wantRoot)
289			})
290		}
291	}
292	
293	// A conflict error still names the submitted and accepted roots distinctly
294	// when invalid bytes are involved, so the two sides of the conflict stay
295	// distinguishable in diagnostics.
296	func TestHeaderConflictErrorDistinguishesInvalidByteRoots(t *testing.T) {
297		dir := t.TempDir()
298		q, err := Open(dir)
299		if err != nil {
300			t.Fatal(err)
301		}
302		defer q.Close()
303		rootFF := string([]byte{0xFF})
304		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: rootFF, Trusted: true}); err != nil {
305			t.Fatal(err)
306		}
307		err = q.UpsertHeader(Header{Chain: "a", Height: 100, Root: string([]byte{0xFE}), Trusted: true})
308		if !errors.Is(err, ErrHeaderConflict) {
309			t.Fatalf("want ErrHeaderConflict, got %v", err)
310		}
311		if !strings.Contains(err.Error(), `\xfe`) || !strings.Contains(err.Error(), `\xff`) {
312			t.Fatalf("conflict error must name both roots distinctly: %v", err)
313		}
314	}
