293		if _, err := q.Submit(env); err != nil {
294			t.Fatal(err)
295		}
296		if _, err := q.Advance(1000); err != nil {
297			t.Fatal(err)
298		}
299		st, _ := q.Query("w")
300		if st.Status != StatusWaiting || st.Attempts != 1 || st.NextRetry != 2000 {
301			t.Fatalf("unexpected pre-reopen state: %+v", st)
302		}
303		if err := q.Close(); err != nil {
304			t.Fatal(err)
305		}
306	
307		q = reopen(t, dir)
308		defer q.Close()
309		echo, err := q.Submit(env)
310		if err != nil {
311			t.Fatalf("byte-identical resubmit after reopen must return existing record: %v", err)
312		}
313		if echo.Msg.Message.Payload != pay || echo.Status != StatusWaiting ||
314			echo.Attempts != 1 || echo.NextRetry != 2000 {
315			t.Fatalf("resubmit must not reschedule or rewrite payload: %+v", echo)
316		}
317		if len(q.Queries()) != 1 {
318			t.Fatal("resubmit must not add a record")
319		}
320		bad := env
321		bad.Message.Payload = "w" + string([]byte{0x00, 0xFF, 0x00})
322		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
323			t.Fatalf("one-byte payload change must conflict: %v", err)
324		}
325		st2, _ := q.Query("w")
326		if st2.Payload != pay || st2.Attempts != 1 || st2.NextRetry != 2000 {
327			t.Fatalf("conflicting resubmit changed the record: %+v", st2)
328		}
329	}
330	
331	// invalidPayloadFrameSize returns the real framed size of a submit entry
332	// carrying tmpl's exact fields with an invalid-UTF-8 payload of n bytes; the
333	// seq-0 omit behavior matches the real queue's first submit.
334	func invalidPayloadFrameSize(t *testing.T, tmpl Envelope, n int) int64 {
335		t.Helper()
336		q, _ := openTempQueue(t)
337		defer q.Close()
338		if err := q.RegisterSource("chain-a"); err != nil {
339			t.Fatal(err)
340		}
341		if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
342			t.Fatal(err)
343		}
344		if _, err := q.Advance(1000); err != nil {
345			t.Fatal(err)
346		}
347		tmpl.Message.Payload = strings.Repeat("\xff", n)
348		before := q.store.size
349		if _, err := q.Submit(tmpl); err != nil {
350			t.Fatal(err)
351		}
352		return q.store.size - before
353	}
354	
355	// Automatic threshold compaction, triggered by an ordinary Submit, must carry
356	// invalid-UTF-8 payloads byte-exactly into the snapshot, including the
357	// oversized payload that supplies the bulk and the small submit that crosses
358	// the threshold; both read identically after reopen.
359	func TestPayloadInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
360		const margin int64 = 4096
361	
362		// Measure the real framed sizes in a gauge queue: size after
363		// source+header+one checkpoint (gaugeBase), the checkpoint frame, the
364		// crossing small submit frame, and the invalid-payload frame math at seq 0.
365		gq, _ := openTempQueue(t)
366		if err := gq.RegisterSource("chain-a"); err != nil {
367			t.Fatal(err)
368		}
369		if err := gq.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
370			t.Fatal(err)
371		}
372		gaugeBase := gq.store.size
373		if _, err := gq.Advance(1000); err != nil {
374			t.Fatal(err)
375		}
376		checkpoint := gq.store.size - gaugeBase
377		gq.Close()
378	
379		cross := payloadEnvelope("cross", 2, "x"+string([]byte{0xFF}))
380		filler := payloadEnvelope("filler", 1, "") // payload length is filled in below
381	
382		// Measure the crossing frame at seq 1 (a placeholder occupies seq 0, as the
383		// filler does in the real queue) in a setup identical to the real one.
384		gq2, _ := openTempQueue(t)
385		if err := gq2.RegisterSource("chain-a"); err != nil {
386			t.Fatal(err)
387		}
388		if err := gq2.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
389			t.Fatal(err)
390		}
391		if _, err := gq2.Advance(1000); err != nil {
392			t.Fatal(err)
393		}
394		if _, err := gq2.Submit(Envelope{Message: Message{
395			ID: "gauge-seq0", From: "chain-a", To: "chain-b", Nonce: 998,
396			Payload: "placeholder", ProofAt: 1,
397		}}); err != nil {
398			t.Fatal(err)
399		}
400		beforeCross := gq2.store.size
401		if _, err := gq2.Submit(cross); err != nil {
402			t.Fatal(err)
403		}
404		crossFrame := gq2.store.size - beforeCross
405		gq2.Close()
406	
407		// Invalid payloads serialize as base64: frame(n) = overhead + EncodedLen(n),
408		// measured for the seq-0 filler (whose seq is JSON-omitted).
409		const probeLen = 4096
410		probeFrame := invalidPayloadFrameSize(t, filler, probeLen)
411		overhead := probeFrame - int64(base64.StdEncoding.EncodedLen(probeLen))
412		targetFillerFrame := compactThreshold - margin - gaugeBase - checkpoint - crossFrame
413		if targetFillerFrame <= overhead {
414			t.Fatalf("setup arithmetic leaves no room for filler: target=%d overhead=%d", targetFillerFrame, overhead)
415		}
416		// Largest invalid byte count whose framed submit stays at the target size.
417		var fillerLen int
418		for lo, hi := 0, int(targetFillerFrame); ; {
419			mid := (lo + hi + 1) / 2
420			if overhead+int64(base64.StdEncoding.EncodedLen(mid)) <= targetFillerFrame {
421				lo = mid
422			} else {
423				hi = mid - 1
424			}
425			if lo == hi {
426				fillerLen = lo
427				break
428			}
429		}
430		filler.Message.Payload = strings.Repeat("\xff", fillerLen)
431	
432		dir := t.TempDir()
433		q, err := Open(dir)
434		if err != nil {
435			t.Fatal(err)
436		}
437		defer q.Close()
438		if err := q.RegisterSource("chain-a"); err != nil {
439			t.Fatal(err)
440		}
441		if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
442			t.Fatal(err)
443		}
444		if q.store.size != gaugeBase {
445			t.Fatalf("base mismatch: gauge %d real %d", gaugeBase, q.store.size)
446		}
447	
448		// Equal-time checkpoint padding (legal with no messages yet) so the small
449		// crossing submit is exactly what crosses 4 MiB; every checkpoint but one
450		// is dropped by the snapshot, which therefore lands margin below.
451		nCheckpoints := int(margin/checkpoint) + 2
452		for i := 0; i < nCheckpoints; i++ {
453			if _, err := q.Advance(1000); err != nil {
454				t.Fatal(err)
455			}
456		}
457		if q.store.size > compactThreshold {
458			t.Fatalf("padding crossed the threshold early: size=%d", q.store.size)
459		}
460		if _, err := q.Submit(filler); err != nil {
461			t.Fatalf("filler submit: %v", err)
462		}
463		if q.store.size > compactThreshold {
464			t.Fatalf("filler crossed the threshold before the crossing submit: size=%d", q.store.size)
465		}
466		if _, err := q.Submit(cross); err != nil {
467			t.Fatalf("crossing submit: %v", err)
468		}
469		if q.store.size > compactThreshold {
470			t.Fatalf("auto-compaction did not shrink the log below the threshold: size=%d", q.store.size)
471		}
472		if err := q.Close(); err != nil {
473			t.Fatal(err)
474		}
475	
476		q = reopen(t, dir)
477		defer q.Close()
478		got, ok := q.Query("filler")
479		if !ok {
480			t.Fatal("filler missing after auto compaction and reopen")
481		}
482		if got.Payload != filler.Message.Payload {
483			t.Fatalf("filler payload changed across auto compaction:\nwant len=%d\ngot  len=%d",
484				len(filler.Message.Payload), len(got.Payload))
485		}
486		if got, ok := q.Query("cross"); !ok || got.Payload != cross.Message.Payload {
487			t.Fatalf("crossing payload lost across auto compaction: ok=%v % x", ok, got.Payload)
488		}
489		// Byte-identical resubmits stay idempotent against the compacted records.
490		if _, err := q.Submit(filler); err != nil {
491			t.Fatalf("filler identical resubmit after compaction: %v", err)
492		}
493		if _, err := q.Submit(cross); err != nil {
494			t.Fatalf("cross identical resubmit after compaction: %v", err)
495		}
496		if len(q.Queries()) != 2 {
497			t.Fatalf("identical resubmits added records: %+v", q.Queries())
498		}
499	}
500	
501	// Existing state directories keep working: payloads an older build saved as
502	// plain JSON — ordinary text, empty and payloads already rewritten to U+FFFD —
503	// are read at face value. The lost bytes are never guessed: the replacement
504	// character stays that payload, and resubmitting the original invalid bytes
505	// conflicts with it.
506	func TestPayloadLegacyRecordsReadAtFaceValue(t *testing.T) {
507		dir := t.TempDir()
508		var raw []byte
509		raw = append(raw, logMagic...)
510		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
511		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
512			T: kindSubmit, Seq: 0, ID: "txt", From: "a", To: "b", Nonce: 1,
513			Payload: "legacy text", ProofAt: 10,
514		}))...)
515		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
516			T: kindSubmit, Seq: 1, ID: "empty", From: "a", To: "b", Nonce: 2, ProofAt: 10,
517		}))...)
518		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
519			T: kindSubmit, Seq: 2, ID: "lost", From: "a", To: "b", Nonce: 3,
520			Payload: replacementCharPayload, ProofAt: 10,
521		}))...)
522		writeRawLog(t, dir, raw)
523	
524		q := reopen(t, dir)
525		defer q.Close()
526		if got, ok := q.Query("txt"); !ok || got.Payload != "legacy text" {
527			t.Fatalf("legacy text payload: ok=%v %q", ok, got.Payload)
528		}
529		if got, ok := q.Query("empty"); !ok || got.Payload != "" {
530			t.Fatalf("legacy empty payload: ok=%v %q", ok, got.Payload)
531		}
532		if got, ok := q.Query("lost"); !ok || got.Payload != replacementCharPayload {
533			t.Fatalf("legacy replacement payload must be taken at face value: ok=%v %x", ok, got.Payload)
534		}
535		lost := Envelope{Message: Message{ID: "lost", From: "a", To: "b", Nonce: 3,
536			Payload: replacementCharPayload, ProofAt: 10}}
537		if _, err := q.Submit(lost); err != nil {
538			t.Fatalf("saved replacement character must resubmit as itself: %v", err)
539		}
540		lost.Message.Payload = string([]byte{0xFF})
541		if _, err := q.Submit(lost); !errors.Is(err, ErrConflict) {
542			t.Fatalf("original invalid bytes must not be guessed back: %v", err)
543		}
544	}
545	
546	// A payloadB64 entry must decode unambiguously: an entry carrying both payload
547	// and payloadB64, or an undecodable payloadB64, is an inconsistent record no
548	// build writes and rejects the directory as corrupt, leaving every byte
549	// untouched.
550	//
551	// Presence is judged by key, not by value: "payload":"" is a legal empty
552	// payload on its own, but together with any payloadB64 it is two
553	// representations at once — both values non-empty, either one empty, both
554	// empty, or the two decoding to the very same bytes all conflict, and field
555	// order does not matter. Every such record below is complete and
556	// checksum-valid and sits at the end of the log, so it must be rejected as
557	// corruption, never dropped as a torn tail or read back by picking either
558	// representation.
559	func TestPayloadB64InconsistentRecordsRejected(t *testing.T) {
560		// Struct-built cases: omitempty drops an empty Payload, so the non-empty
561		// plain clash and the undecodable base64 can use the typed entry.
562		structEntries := map[string]*logEntry{
563			"both payload and payloadB64": {
564				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
565				Payload: "x", PayloadB64: "eA==", ProofAt: 10,
566			},
567			"undecodable payloadB64": {
568				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
569				PayloadB64: "!!!not-base64!!!", ProofAt: 10,
570			},
571		}
572		// Raw-JSON cases: the "payload":"" key must literally be present, which the
573		// omitempty struct tag would erase on marshal.
574		rawPayloads := map[string]string{
575			"empty payload plus payloadB64 of 0xff":              `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":"/w=="}`,
576			"empty payload plus empty payloadB64, equal decoded": `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":""}`,
577			"non-empty payload plus empty payloadB64":            `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"x","payloadB64":""}`,
578			"plain and payloadB64 decode to the same bytes":      `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"eA==","payload":"x"}`,
579			"both representations, base64 key first":             `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"/w==","payload":""}`,
580		}
581		for name, e := range structEntries {
582			t.Run(name, func(t *testing.T) {
583				dir := t.TempDir()
584				var raw []byte
585				raw = append(raw, logMagic...)
586				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
587				raw = append(raw, encodeFrame(mustMarshal(e))...)
588				writeRawLog(t, dir, raw)
589				assertCorruptAndUntouched(t, dir, raw)
590			})
591		}
592		for name, payload := range rawPayloads {
593			t.Run(name, func(t *testing.T) {
594				dir := t.TempDir()
595				var raw []byte
596				raw = append(raw, logMagic...)
597				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
598				raw = append(raw, encodeFrame([]byte(payload))...)
599				writeRawLog(t, dir, raw)
600				assertCorruptAndUntouched(t, dir, raw)
601			})
602		}
603	}
604	
605	// The empty payload keeps its long-standing meaning through every legal
606	// on-disk shape, and a sole payloadB64 still restores its bytes: the new
607	// presence-based clash check must never mistake an omitted key for an
608	// empty-but-present one. Only payload:"" (the shape this build writes), both
609	// keys absent (a historical record), a sole empty payloadB64 all restore the
610	// empty payload, and a sole non-empty payloadB64 restores its exact bytes; the
611	// restored content then participates in the ordinary same-id comparison.
612	func TestPayloadEmptyOmittedAndSoleB64StillAccepted(t *testing.T) {
613		payFF := string([]byte{0xFF})
614		cases := map[string]struct {
615			payload     string
616			wantPayload string
617			badResubmit string
618		}{
619			"explicit empty payload": {
620				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":""}`,
621				wantPayload: "",
622				badResubmit: "x",
623			},
624			"both payload keys omitted (historical empty payload)": {
625				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10}`,
626				wantPayload: "",
627				badResubmit: "x",
628			},
629			"sole empty payloadB64 is the empty payload": {
630				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":""}`,
631				wantPayload: "",
632				badResubmit: "x",
633			},
634			"sole payloadB64 restores its bytes": {
635				payload:     `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"/w=="}`,
636				wantPayload: payFF,
637				badResubmit: "",
638			},
639		}
640		for name, tc := range cases {
641			t.Run(name, func(t *testing.T) {
642				dir := t.TempDir()
643				var raw []byte
644				raw = append(raw, logMagic...)
645				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
646				raw = append(raw, encodeFrame([]byte(tc.payload))...)
647				writeRawLog(t, dir, raw)
648	
649				q := reopen(t, dir)
650				defer q.Close()
651				got, ok := q.Query("m")
652				if !ok {
653					t.Fatal("restored message missing")
654				}
655				if !bytes.Equal([]byte(got.Payload), []byte(tc.wantPayload)) {
656					t.Fatalf("restored payload = % x, want % x", got.Payload, tc.wantPayload)
657				}
658				// A byte-identical resubmit returns the existing record; a differing
659				// payload conflicts, proving the restored bytes are the real content.
660				same := Envelope{Message: Message{
661					ID: "m", From: "a", To: "b", Nonce: 1,
662					Payload: tc.wantPayload, ProofAt: 10,
663				}}
664				if echo, err := q.Submit(same); err != nil || echo.Msg.Message.Payload != tc.wantPayload {
665					t.Fatalf("identical resubmit of restored payload: echo=%+v err=%v", echo, err)
666				}
667				diff := same
668				diff.Message.Payload = tc.badResubmit
669				if _, err := q.Submit(diff); !errors.Is(err, ErrConflict) {
670					t.Fatalf("different content must conflict with restored payload % x: %v", tc.wantPayload, err)
671				}
672			})
673		}
674	}
675	
676	// A complete dual-payload submit record is corruption even when perfectly
677	// good records precede it — including the submit entry a compaction writes to
678	// restore an already processed message, followed by its state entry. Open
679	// refuses the whole directory with ErrCorrupt, returns no usable queue and
680	// leaves the complete offending frame (and everything before it)
681	// byte-for-byte in place, so none of the earlier normal messages can be
682	// queried either.
683	func TestPayloadDualRepresentationRejectedAfterNormalRecordsAndInSnapshot(t *testing.T) {
684		t.Run("normal submit then dual-payload final record", func(t *testing.T) {
685			dir := t.TempDir()
686			var raw []byte
687			raw = append(raw, logMagic...)
688			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
689			raw = append(raw, encodeFrame(mustMarshal(&logEntry{
690				T: kindSubmit, Seq: 0, ID: "ok", From: "a", To: "b", Nonce: 1,
691				Payload: "normal", ProofAt: 10,
692			}))...)
693			raw = append(raw, encodeFrame([]byte(
694				`{"t":"submit","seq":1,"id":"bad","from":"a","to":"b","nonce":2,"proofAt":10,"payload":"","payloadB64":"/w=="}`))...)
695			writeRawLog(t, dir, raw)
696			assertCorruptAndUntouched(t, dir, raw)
697		})
698	
699		t.Run("dual-payload submit in a compacted snapshot with its state", func(t *testing.T) {
700			dir := t.TempDir()
701			var raw []byte
702			raw = append(raw, logMagic...)
703			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
704			// This is the submit/state ordering compact() writes to restore a
705			// delivered message; the dual-payload submit must reject the snapshot.
706			raw = append(raw, encodeFrame([]byte(
707				`{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"","payloadB64":"/w=="}`))...)
708			raw = append(raw, encodeFrame(mustMarshal(&logEntry{
709				T: kindState, Now: 1000, ID: "m", Status: StatusSuccess, Attempts: 1,
710				ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
711			}))...)
712			writeRawLog(t, dir, raw)
713			assertCorruptAndUntouched(t, dir, raw)
714		})
715	}
