24	// idEnvelope builds a pending envelope keyed by id; callers supply distinct
25	// nonces so processing one message can never replay another.
26	func idEnvelope(id string, nonce uint64, proofAt int64) Envelope {
27		return Envelope{
28			Message: Message{
29				ID: id, From: "chain-a", To: "chain-b", Nonce: nonce,
30				Payload: "payload-" + id, ProofAt: proofAt,
31			},
32		}
33	}
