353	// Automatic threshold compaction, triggered by an ordinary Submit, must carry
354	// invalid-UTF-8 ids byte-exactly into the snapshot: an oversized raw-bytes id
355	// supplies the bulk, the small crossing submit pushes past 4 MiB, and both
356	// read identically, in order, after reopen.
357	func TestIDInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
358		const margin int64 = 4096
359	
360		versionFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))))
361		baseSize := int64(len(logMagic)) + versionFrame
362		checkpointFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindAdvance, Now: 1000}))))
363	
364		crossID := "cross" + string([]byte{0xFF})
365		crossEntry := &logEntry{T: kindSubmit, Seq: 1, From: "chain-a", To: "chain-b", Nonce: 2, ProofAt: 1}
366		crossEntry.setID(crossID)
367		crossFrame := int64(len(encodeFrame(mustMarshal(crossEntry))))
368	
369		// The filler is the seq-0 submit: its seq zero-value is JSON-omitted, so
370		// the framed size measured here is exactly what the real queue writes.
371		fillerFrame := func(idLen int) int64 {
372			e := &logEntry{T: kindSubmit, From: "chain-a", To: "chain-b", Nonce: 1, ProofAt: 1}
373			e.setID(strings.Repeat("\xff", idLen))
374			return int64(len(encodeFrame(mustMarshal(e))))
375		}
376		overhead := fillerFrame(1) - int64(base64.StdEncoding.EncodedLen(1))
377	
378		nCheckpoints := int(margin/checkpointFrame) + 2
379		targetFillerFrame := compactThreshold - margin - baseSize -
380			int64(nCheckpoints)*checkpointFrame - crossFrame
381		if targetFillerFrame <= overhead {
382			t.Fatalf("setup arithmetic leaves no room: target=%d overhead=%d", targetFillerFrame, overhead)
383		}
384		var fillerLen int
385		for lo, hi := 0, int(targetFillerFrame); ; {
386			mid := (lo + hi + 1) / 2
387			if fillerFrame(mid) <= targetFillerFrame {
388				lo = mid
389			} else {
390				hi = mid - 1
391			}
392			if lo == hi {
393				fillerLen = lo
394				break
395			}
396		}
397		if fillerLen == 0 {
398			t.Fatal("filler id length resolved to zero")
399		}
400		fillerID := strings.Repeat("\xff", fillerLen)
401		filler := idEnvelope(fillerID, 1, 1)
402		filler.Message.Payload = ""
403		cross := idEnvelope(crossID, 2, 1)
404		cross.Message.Payload = ""
405	
406		dir := t.TempDir()
407		q, err := Open(dir)
408		if err != nil {
409			t.Fatal(err)
410		}
411		defer q.Close()
412		if q.store.size != baseSize {
413			t.Fatalf("base size mismatch: want %d got %d", baseSize, q.store.size)
414		}
415		// Equal-time checkpoint padding (legal with no messages yet) so the
416		// crossing submit is exactly what trips 4 MiB; snapshots drop the
417		// checkpoints, so the compacted log lands margin below the threshold.
418		for i := 0; i < nCheckpoints; i++ {
419			if _, err := q.Advance(1000); err != nil {
420				t.Fatal(err)
421			}
422		}
423		if q.store.size > compactThreshold {
424			t.Fatalf("padding crossed the threshold early: %d", q.store.size)
425		}
426		if _, err := q.Submit(filler); err != nil {
427			t.Fatalf("filler submit: %v", err)
428		}
429		if q.store.size > compactThreshold {
430			t.Fatalf("filler crossed before the crossing submit: %d", q.store.size)
431		}
432		if _, err := q.Submit(cross); err != nil {
433			t.Fatalf("crossing submit: %v", err)
434		}
435		if q.store.size > compactThreshold {
436			t.Fatalf("auto-compaction did not shrink the log: %d", q.store.size)
437		}
438		if err := q.Close(); err != nil {
439			t.Fatal(err)
440		}
441	
442		q = reopen(t, dir)
443		defer q.Close()
444		got, ok := q.Query(fillerID)
445		if !ok || got.ID != fillerID {
446			t.Fatalf("filler id changed across auto compaction: ok=%v idlen=%d gotlen=%d",
447				ok, len(fillerID), len(got.ID))
448		}
449		if got, ok := q.Query(crossID); !ok || got.ID != crossID {
450			t.Fatalf("crossing id lost across auto compaction: ok=%v % x", ok, got.ID)
451		}
452		all := q.Queries()
453		if len(all) != 2 || all[0].ID != fillerID || all[1].ID != crossID {
454			t.Fatalf("order after auto compaction: %d rows % x / % x", len(all), all[0].ID, all[1].ID)
455		}
456	
457		raw, err := os.ReadFile(filepath.Join(dir, logName))
458		if err != nil {
459			t.Fatal(err)
460		}
461		if !bytes.Contains(raw, []byte(`"idB64":"`)) {
462			t.Fatalf("invalid-UTF-8 ids not stored byte-exactly: %s", raw[:200])
463		}
464		if bytes.Contains(raw, []byte(replacementCharID)) {
465			t.Fatalf("compacted log contains replacement characters for raw-byte ids")
466		}
467	}
