469	// Existing state directories keep their meaning: ids an older build saved as
470	// plain JSON are read at face value. A saved U+FFFD is that character, not the
471	// 0xFF an old build may have lost — resubmitting the character idempotently
472	// returns the record, while resubmitting the original invalid bytes conflicts
473	// rather than resurrecting or merging.
474	func TestIDLegacyRecordsReadAtFaceValue(t *testing.T) {
475		dir := t.TempDir()
476		var raw []byte
477		raw = append(raw, logMagic...)
478		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
479		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
480			T: kindSubmit, Seq: 0, ID: "txt", From: "a", To: "b", Nonce: 1,
481			Payload: "legacy text", ProofAt: 10,
482		}))...)
483		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
484			T: kindSubmit, Seq: 1, ID: replacementCharID, From: "a", To: "b",
485			Nonce: 2, Payload: "p", ProofAt: 10,
486		}))...)
487		writeRawLog(t, dir, raw)
488	
489		q := reopen(t, dir)
490		defer q.Close()
491		if got, ok := q.Query("txt"); !ok || got.ID != "txt" {
492			t.Fatalf("legacy text id: ok=%v %q", ok, got.ID)
493		}
494		got, ok := q.Query(replacementCharID)
495		if !ok || got.ID != replacementCharID {
496			t.Fatalf("legacy replacement id must be read at face value: ok=%v % x", ok, got.ID)
497		}
498		saved := Envelope{Message: Message{
499			ID: replacementCharID, From: "a", To: "b", Nonce: 2, Payload: "p", ProofAt: 10,
500		}}
501		if _, err := q.Submit(saved); err != nil {
502			t.Fatalf("saved replacement character id must resubmit as itself: %v", err)
503		}
504		// The invalid bytes the old build lost are not guessed back: 0xFF is a
505		// different id from the saved U+FFFD, so it enqueues a distinct record and
506		// neither id finds the other's message.
507		original := saved
508		original.Message.ID = string([]byte{0xFF})
509		if _, err := q.Submit(original); err != nil {
510			t.Fatalf("original invalid bytes are a distinct id, not a conflict with saved U+FFFD: %v", err)
511		}
512		if got, ok := q.Query(replacementCharID); !ok || got.ID != replacementCharID {
513			t.Fatalf("saved U+FFFD record changed: ok=%v % x", ok, got.ID)
514		}
515		if got, ok := q.Query(string([]byte{0xFF})); !ok || got.ID != string([]byte{0xFF}) {
516			t.Fatalf("raw 0xFF id must keep its own new record: ok=%v % x", ok, got.ID)
517		}
518		if len(q.Queries()) != 3 {
519			t.Fatalf("raw 0xFF and saved U+FFFD must not merge: %+v", q.Queries())
520		}
521	}
522	
523	// A checksum-valid record that carries both a plain field and its base64 form,
524	// or an undecodable base64 field, is an inconsistent record no build writes:
525	// opening returns ErrCorrupt and leaves the file byte-for-byte untouched.
526	func TestIDB64InconsistentRecordsRejected(t *testing.T) {
527		submitBoth := &logEntry{
528			T: kindSubmit, Seq: 0, ID: "m", IDB64: "bQ==", From: "a", To: "b",
529			Nonce: 1, Payload: "p", ProofAt: 10,
530		}
531		submitBad := &logEntry{
532			T: kindSubmit, Seq: 0, IDB64: "!!!not-base64!!!", From: "a", To: "b",
533			Nonce: 1, Payload: "p", ProofAt: 10,
534		}
535		successBoth := func() []*logEntry {
536			return []*logEntry{
537				{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 10},
538				{T: kindResult, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok",
539					Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1,
540					ConsumeBy: "m", ConsumeByB64: "bQ=="},
541			}
542		}
543		successBadBy := func() []*logEntry {
544			return []*logEntry{
545				{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 10},
546				{T: kindResult, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok",
547					Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1,
548					ConsumeByB64: "!!!not-base64!!!"},
549			}
550		}
551		waitingBadReason := func() []*logEntry {
552			return []*logEntry{
553				{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 100},
554				{T: kindResult, Now: 1000, ID: "w", Status: StatusWaiting, ReasonB64: "!!!not-base64!!!",
555					Attempts: 1, NextRetry: 2000},
556			}
557		}
558	
559		cases := map[string][]*logEntry{
560			"submit with both id and idB64":         {submitBoth},
561			"submit with undecodable idB64":         {submitBad},
562			"success with both consumeBy forms":     successBoth(),
563			"success with undecodable consumeByB64": successBadBy(),
564			"waiting with undecodable reasonB64":    waitingBadReason(),
565		}
566		for name, entries := range cases {
567			t.Run(name, func(t *testing.T) {
568				dir := t.TempDir()
569				var data []byte
570				data = append(data, logMagic...)
571				data = append(data, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
572				for _, e := range entries {
573					data = append(data, encodeFrame(mustMarshal(e))...)
574				}
575				writeRawLog(t, dir, data)
576				assertCorruptAndUntouched(t, dir, data)
577			})
578		}
579	}
580	
581	// The empty id stays rejected by the Go API as an invalid argument.
582	func TestIDEmptyStillRejected(t *testing.T) {
583		q, _ := openTempQueue(t)
584		defer q.Close()
585		_, err := q.Submit(Envelope{Message: Message{ID: "", From: "a", To: "b", Nonce: 1, ProofAt: 1}})
586		if !errors.Is(err, ErrInvalidArg) {
587			t.Fatalf("empty id: want ErrInvalidArg, got %v", err)
588		}
589	}
